void EntityWeaponAttack(Entity* self) {
    s16 deltaX;

    switch (self->step) {
    case 0:
        SetSpriteBank1(g_Animset);
        self->animSet = ANIMSET_OVL(16);
        self->palette = PAL_UNK_110;
        self->unk5A = 0x64;

        if (g_HandId != 0) {
            self->animSet += 2;
            self->palette += 0x18;
            self->unk5A += 2;
        }

        self->zPriority = PLAYER.zPriority + 2;
        self->facingLeft = PLAYER.facingLeft;
        self->flags = FLAG_UNK_100000 | FLAG_POS_PLAYER_LOCKED;
        self->anim = D_9E000_8017A77C;

        deltaX = (self->facingLeft) ? 32 : -32;
        self->posY.i.hi -= 6;
        self->posX.i.hi += deltaX;

        g_api.PlaySfx(SFX_MAGIC_WEAPON_APPEAR_A);
        DestroyEntityWeapon(1);
        g_Player.timers[10] = 4;
        self->step++;
        break;

    case 1:
        if (self->poseTimer < 0) {
            self->ext.timer.t = 16;
            self->drawFlags |= DRAW_MENU;
            self->step++;
        }
        if (self->pose == 20 && self->poseTimer == 2 &&
            g_api.CreateEntFactoryFromEntity(self, WFACTORY(0x38, 0), 0)) {
            g_api.PlaySfx(SFX_ARROW_SHOT_A);
        }
        break;

    case 2:
        self->ext.timer.t--;
        if (self->ext.timer.t == 0) {
            DestroyEntity(self);
        }
        break;
    }
}

s32 func_ptr_80170004(Entity* self) {
    switch (self->step) {
    case 0:
        if (self->ext.weapon.parent->entityId == 0) {
            DestroyEntity(self);
            break;
        }
        self->facingLeft = self->ext.weapon.parent->facingLeft;
        self->animSet = self->ext.weapon.parent->animSet;
        self->anim = D_9E000_8017A800;
        self->zPriority = PLAYER.zPriority + 2;
        self->unk5A = self->ext.weapon.parent->unk5A;
        self->palette = self->ext.weapon.parent->palette;
        self->flags = FLAG_POS_CAMERA_LOCKED | FLAG_UNK_100000;
        SetSpeedX(FIX(5));
        self->ext.weapon.equipId = self->ext.weapon.parent->ext.weapon.equipId;
        SetWeaponProperties(self, 0);
        self->hitboxOffX = 8;
        self->hitboxWidth = 8;
        self->hitboxHeight = 4;
        self->step++;
        break;
    case 1:
        if (self->hitFlags == 1) {
            self->poseTimer = 0;
            self->pose = 0;
            self->anim = D_9E000_8017A760;
            self->step++;
        } else {
            self->posX.val += self->velocityX;
        }
        break;
    case 2:
        if (self->poseTimer < 0) {
            DestroyEntity(self);
        }
        break;
    }
}

